interface LanguageContextValue {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (key: string, values?: Record<string, string | number>) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);

function getInitialLanguage(): Language {
  try {
    const saved = localStorage.getItem('vitalis_language');
    if (saved === 'en' || saved === 'hi' || saved === 'te') {
      activeLanguage = saved;
      return saved;
    }
  } catch {
    // Storage can be unavailable in private or restricted browser contexts.
  }
  const browserLanguage = navigator.language.toLowerCase();
  activeLanguage = browserLanguage.startsWith('te') ? 'te' : browserLanguage.startsWith('hi') ? 'hi' : 'en';
  return activeLanguage;
}

export function translateStaticText(source: string): string {
  return activeLanguage === 'en' ? source : interfaceTranslations[activeLanguage][source] ?? source;
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(getInitialLanguage);
  const setLanguage = (nextLanguage: Language) => {
    activeLanguage = nextLanguage;
    try {
      localStorage.setItem('vitalis_language', nextLanguage);
      document.documentElement.lang = nextLanguage;
    } catch {
      // The selected language still applies for this page view.
    }
    setLanguageState(nextLanguage);
  };

  useEffect(() => {
    document.documentElement.lang = language;
    try {
      localStorage.setItem('vitalis_language', language);
    } catch {
      // The selected language still applies for this page view.
    }
  }, [language]);

  const value = useMemo<LanguageContextValue>(() => ({
    language,
    setLanguage,
    t: (key, values) => {
      let text = dictionaries[language][key] ?? dictionaries.en[key] ?? key;
      if (values) {
        text = text.replace(/\{(\w+)\}/g, (match, name: string) => String(values[name] ?? match));
      }
      return text;
    },
  }), [language]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used inside LanguageProvider');
  return context;
}
